INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_520001', 'MCQ',
 'A nurse is preparing an 18-month-old toddler for insertion of an intravenous cannula on the paediatric ward. Which approach should the nurse use?',
 'A child of 18 months is in the sensorimotor stage and lives entirely in the present, so advance preparation carries no meaning because the child cannot hold a future event in mind. Pre-procedure teaching is therefore directed at the parents, who carry the information and stay with the child, while the toddler is prepared during the procedure itself using short present-tense sentences and comfort from a familiar adult. Drawing, rehearsal and symbolic representation belong to older children who can stand outside an event and imagine it.',
 '{"options":[{"id":"A","text":"Explain the whole procedure to the toddler in simple words two days beforehand"},{"id":"B","text":"Give the explanation to the parents beforehand and talk the toddler through each step in the present tense as it happens"},{"id":"C","text":"Ask the toddler to draw a picture of the cannula the day before the procedure"},{"id":"D","text":"Give no explanation at all, because a toddler cannot understand what is happening"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A sensorimotor child cannot hold a future event in mind, so a two-day lead time produces anxiety without understanding.","B":"Correct. For a sensorimotor child the teaching goes to the parents beforehand, and the child is prepared during the procedure with present-tense commentary and comfort.","C":"Incorrect. Drawing requires symbolic representation, which does not emerge until the preoperational stage.","D":"Incorrect. Saying nothing ignores both the need for parental preparation and the toddler need for present-tense reassurance during the procedure."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Cognitive development and procedure preparation', 'Sensorimotor stage',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520002', 'MCQ',
 'A 4-year-old is scheduled for a tonsillectomy at 08:00 tomorrow. The mother asks the nurse when she should tell the child about the operation. Which reply is BEST?',
 'A preschooler is in the preoperational stage, where magical thinking is strong and the sense of time is poor, so a long waiting period is filled with frightening invented detail rather than growing understanding. Preparation is given close to the event, in hours rather than days, using simple future-tense words and play. Waiting until the child is already in the anaesthetic room removes every chance to ask questions or rehearse, which is equally unhelpful.',
 '{"options":[{"id":"A","text":"Tell him now, so he has the whole night to get used to the idea"},{"id":"B","text":"Tell him a short time before you leave for the hospital in the morning"},{"id":"C","text":"Tell him nothing, since he will be asleep for the operation anyway"},{"id":"D","text":"Wait until he is in the anaesthetic room and then explain what will happen"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A long lead time gives a preoperational child many hours to imagine frightening things without the reasoning needed to correct them.","B":"Correct. Preschoolers are prepared shortly before the event in simple future-tense words, so anxiety is not prolonged.","C":"Incorrect. When nothing is said the preschooler constructs an explanation, and that explanation is very often that the operation is a punishment.","D":"Incorrect. Preparation in the anaesthetic room leaves no time for questions, choices or therapeutic play."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Cognitive development and procedure preparation', 'Preoperational stage',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520003', 'MCQ',
 'A 9-year-old is admitted for a lumbar puncture that is planned for two days from now. Which preparation is most appropriate for a child of this age?',
 'School-age children reason logically about real objects, want to know the sequence and the rules, and cope better when told a day or two in advance so they have time to rehearse and build a sense of control. Handling the real equipment and demonstrating on a doll turns an abstract threat into something concrete that can be examined. Delaying the explanation to the morning of the procedure, or until after sedation, removes exactly the rehearsal time this age group uses to cope.',
 '{"options":[{"id":"A","text":"Explain the procedure only after the sedation has been given"},{"id":"B","text":"Describe the steps in order now, show the equipment and let the child handle a syringe and practise on a doll"},{"id":"C","text":"Tell the child on the morning of the procedure so that there is no time to worry"},{"id":"D","text":"Give the parents a leaflet and ask them to explain it in their own words"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Explaining after sedation denies the school-age child the rehearsal and sense of control that reduce distress.","B":"Correct. Concrete operational children learn from a step-by-step sequence, real equipment and a demonstration given one to two days ahead.","C":"Incorrect. A school-age child uses the waiting time to prepare, so a same-morning explanation shortens rather than protects.","D":"Incorrect. Delegating the whole explanation to the parents leaves accuracy to chance and omits the equipment and demonstration this age needs."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Cognitive development and procedure preparation', 'Concrete operational stage',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520004', 'SATA',
 'A 15-year-old girl is admitted for an appendicectomy later today. Which nursing actions are appropriate when preparing this client for surgery? Select all that apply.',
 'Adolescents have reached formal operational thought and can reason abstractly, weigh consequences and consider outcomes that have not yet happened, so they are prepared in much the same way as an adult client. Body image, appearance and the effect on school and friendships are central concerns at this stage and belong in the discussion, as does a genuine share in decisions about care. Doll demonstration is a preschool and school-age technique that feels patronising to an adolescent, and deliberately shortening the lead time removes the reasoning time this age group uses.',
 '{"options":[{"id":"A","text":"Explain the procedure and the reasons for it in the same detail used for an adult client"},{"id":"B","text":"Offer time alone with the nurse so questions can be asked without the parents present"},{"id":"C","text":"Discuss how the scar and the recovery period will affect appearance and school attendance"},{"id":"D","text":"Limit the explanation to a few minutes before transfer so there is no time to worry"},{"id":"E","text":"Ask which decisions about her care she would like to make for herself"},{"id":"F","text":"Use a doll to demonstrate where the incision will be made"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Formal operational thinking allows an adolescent to follow an adult-level explanation including rationale and risk.","B":"Correct. Private time supports developing autonomy and allows questions that would not be asked in front of parents.","C":"Correct. Body image and peer and school life are central adolescent concerns and should be raised rather than avoided.","D":"Incorrect. Very short notice is a technique for preschoolers, not for adolescents, who use reasoning time to prepare.","E":"Correct. Sharing real decisions supports identity formation and increases cooperation with care.","F":"Incorrect. Doll demonstration suits preschool and school-age children and is likely to feel belittling to a 15-year-old."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Cognitive development and procedure preparation', 'Formal operational stage',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520005', 'SATA',
 'A 5-year-old is due for a painful burn dressing change. Which nursing actions use therapeutic play appropriately for a child of this age? Select all that apply.',
 'Therapeutic play lets a preschooler rehearse a threatening event, handle the equipment safely and take back some control over what is being done. It works only when the information given is honest, because false reassurance that nothing will hurt destroys trust for every later procedure. Play after the event matters as much as play before it, since preschoolers work through what happened by repeating it in their own way, and no explanation should ever link the treatment to the behaviour of the child.',
 '{"options":[{"id":"A","text":"Let the child bandage a teddy bear before the dressing change begins"},{"id":"B","text":"Allow the child to hold a needleless syringe and handle the dressing packs"},{"id":"C","text":"Tell the child the dressing change will not hurt at all"},{"id":"D","text":"Offer the child a choice of which hand to hold the teddy in during the procedure"},{"id":"E","text":"Explain that the dressing change is needed because the child was careless near the cooker"},{"id":"F","text":"Give the child dolls and dressing materials to play out the procedure afterwards"}]}'::jsonb,
 '{"answers":["A","B","D","F"],"feedback":{"A":"Correct. Rehearsing on a teddy lets the preschooler master the sequence before it is done to the body.","B":"Correct. Handling real equipment in a safe form reduces the strangeness of the procedure and gives the child some control.","C":"Incorrect. Promising no pain is dishonest and destroys the trust needed for every later procedure.","D":"Correct. A limited but genuine choice restores control without changing the fact that the dressing must be changed.","E":"Incorrect. Linking treatment to the behaviour of the child reinforces the preschool belief that pain is punishment.","F":"Correct. Post-procedural play lets a preschooler work through what happened by repeating it on their own terms."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Integumentary',
 'Therapeutic play', 'Preparation for a painful procedure',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520006', 'MCQ',
 'A 3-year-old receiving an intramuscular injection cries and says, I am getting this because I was naughty. Which response by the nurse is BEST?',
 'Preschoolers reason by magical thinking and see themselves as the cause of events around them, so illness and treatment are commonly interpreted as punishment for something they did or thought. The nurse corrects the misconception plainly and simply, links the injection to getting better, and does not shame the child for crying. Agreeing with the punishment idea deepens the guilt, and a pharmacological explanation exceeds what preoperational reasoning can hold.',
 '{"options":[{"id":"A","text":"Tell the child that being naughty has nothing to do with it, and that the injection is medicine to help the body get better"},{"id":"B","text":"Agree that children who behave well usually need fewer injections"},{"id":"C","text":"Explain how the medicine travels in the blood to fight the infection"},{"id":"D","text":"Tell the child that big children do not cry when they have injections"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. The magical-thinking misconception is corrected directly and the injection is reframed simply as medicine that helps.","B":"Incorrect. Linking behaviour to treatment confirms the punishment belief and increases guilt.","C":"Incorrect. A physiological explanation is beyond preoperational reasoning and does not address the fear being expressed.","D":"Incorrect. Shaming the child for crying adds to distress and teaches the child to hide fear rather than express it."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Magical thinking in the preschooler', 'Illness perceived as punishment',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_520007', 'MATRIX',
 'A nurse is planning how to prepare four children for scheduled procedures. For each client, select the preparation approach that matches the developmental stage.',
 'The timing and the form of procedure preparation follow cognitive development rather than the complexity of the procedure. Sensorimotor infants and young toddlers are prepared through the parents and talked through the event as it happens; preoperational preschoolers are prepared a few hours before using play and simple future-tense words; concrete operational school-age children are prepared one to two days ahead with a step-by-step demonstration; adolescents in formal operations are prepared as adults, with full rationale and shared decisions. Matching the approach to the stage is what turns preparation into reassurance instead of a longer period of dread.',
 '{"rows":[{"id":"r1","text":"A 14-month-old having a nasogastric tube passed"},{"id":"r2","text":"A 4-year-old having a plaster cast applied"},{"id":"r3","text":"An 8-year-old having a bone marrow aspiration"},{"id":"r4","text":"A 16-year-old having a knee arthroscopy"}],"columns":[{"id":"c1","text":"Prepare the parents beforehand and talk the child through it as it happens"},{"id":"c2","text":"Prepare a few hours before, using play and simple future-tense words"},{"id":"c3","text":"Prepare one to two days before, with a step-by-step demonstration"},{"id":"c4","text":"Prepare as for an adult, with full rationale and shared decisions"}],"row_label":"Client"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c4"},"feedback":{}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Not applicable',
 'Cognitive development and procedure preparation', 'Matching timing to developmental stage',
 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 'Select one column for each row.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_CLZ_520008', 'CLOZE',
 'A nurse is preparing a 4-year-old for a scheduled procedure. The nurse should begin the explanation {1} and should describe what will happen using {2}. Select the option that completes each sentence.',
 'Preschool children have an unreliable sense of time and a strong tendency to fill gaps with frightening imagined detail, so preparation is deliberately kept close to the event rather than given days ahead. The language used is short, simple and in the future tense, supported by a doll or puppet so the child can see and handle what is being described. Anatomy diagrams and surgical terminology depend on abstract reasoning that has not yet developed at this age.',
 '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"one week before the procedure"},{"id":"c2","text":"a few hours before the procedure"},{"id":"c3","text":"only after sedation has been given"}]},{"id":"b2","choices":[{"id":"c1","text":"simple words together with a doll or puppet"},{"id":"c2","text":"a printed anatomy diagram"},{"id":"c3","text":"the medical terms used by the surgeon"}]}]}'::jsonb,
 '{"answers":{"b1":"c2","b2":"c1"},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Cognitive development and procedure preparation', 'Preoperational teaching method',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 'Complete the sentence by choosing from each drop-down.', 2, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520009', 'MCQ',
 'An 8-year-old with newly diagnosed type 1 diabetes mellitus has learned to draw up and give the insulin injection correctly. The mother asks whether the child can now manage the diabetes independently. Which reply by the nurse is most accurate?',
 'Being able to carry out a psychomotor skill is not the same as being able to manage a long-term condition. School-age children in concrete operations readily master the technical steps of drawing up insulin and testing blood glucose, but judgement tasks such as adjusting a dose, interpreting a result and recognising and treating hypoglycaemia require abstract reasoning that develops during adolescence. Supervision is therefore withdrawn task by task rather than all at once when the injection technique is mastered.',
 '{"options":[{"id":"A","text":"Yes, a child who can give the injection can be left to manage the whole regimen"},{"id":"B","text":"The child can give the injection, but an adult still needs to decide the dose and interpret the blood glucose readings"},{"id":"C","text":"The child should not give the injection at all until 12 years of age"},{"id":"D","text":"Any independence in diabetes care should be delayed until the child leaves school"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Mastery of a skill does not bring the abstract judgement needed to adjust doses or interpret readings.","B":"Correct. School-age children can perform the technique reliably, while dose decisions and result interpretation still need an adult until abstract reasoning matures.","C":"Incorrect. Withholding a skill the child has already mastered removes control and damages self-esteem during the industry stage.","D":"Incorrect. Independence is built gradually through childhood rather than deferred wholesale to adulthood."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Endocrine',
 'Self-care readiness in childhood', 'Performing a skill versus managing a condition',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520010', 'MCQ',
 'A 2-year-old admitted three days ago cried and clung to the mother on admission but now lies quietly, does not play, and does not look up when the mother enters the cubicle. A student nurse comments that the toddler has settled in well. Which interpretation by the nurse is correct?',
 'Separation anxiety in the hospitalised toddler moves through protest, marked by loud crying and clinging, then despair, marked by withdrawal, apathy and stillness, and finally detachment, in which the child appears friendly with everyone and shows no special preference for the parent. The quiet middle phase is regularly misread by staff as the child settling in, when in fact distress is deepening. The nursing response is to increase parental presence and continuity of caregiver rather than to treat the silence as progress.',
 '{"options":[{"id":"A","text":"The toddler has adapted well to the ward routine"},{"id":"B","text":"The toddler is showing the despair phase of separation anxiety and needs increased parental presence"},{"id":"C","text":"The toddler is forming an appropriate attachment to the nursing staff"},{"id":"D","text":"The toddler is showing early signs of a depressive disorder and needs psychiatric referral"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Quietness and withdrawal in a hospitalised toddler signal deepening distress, not adaptation.","B":"Correct. Withdrawal, apathy and loss of interest in the parent are the hallmarks of the despair phase and call for more parental presence and continuity of caregiver.","C":"Incorrect. Attachment to staff would show as engagement and preference, not as stillness and no response to the mother.","D":"Incorrect. This is a recognised and reversible response to separation rather than a psychiatric disorder."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Separation anxiety in the hospitalised toddler', 'Despair phase',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_520011', 'MCQ',
 'A 4-year-old who has been dry at night for a year has wet the bed on each of the three nights since admission. The father is embarrassed and scolds the child in front of the nurse. Which response by the nurse is BEST?',
 'Regression, the return to an earlier and more secure pattern of behaviour, is one of the commonest responses of a young child to the loss of control that illness and hospitalisation bring. Bedwetting, thumb sucking, baby talk and clinging are expected, temporary and resolve once the child is home and secure again. Scolding adds shame to an already stressful experience and tends to prolong the regression, so the nursing action is to explain the pattern to the parent and remove the blame.',
 '{"options":[{"id":"A","text":"Explain that this is a common and temporary response to being in hospital and ask the father not to scold the child for it"},{"id":"B","text":"Advise the father to restrict all fluids from midday onwards"},{"id":"C","text":"Arrange for a urinary catheter so that the bed stays dry"},{"id":"D","text":"Ask the doctor to prescribe a bladder antispasmodic"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Regression is an expected, temporary response to hospitalisation, and removing the shaming is the key nursing action.","B":"Incorrect. Severe fluid restriction risks dehydration in a young child and does not address the cause of the regression.","C":"Incorrect. Catheterisation is invasive, introduces infection risk and would further reduce the sense of control this child has already lost.","D":"Incorrect. There is no bladder pathology here, so medication would treat a problem that does not exist."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Response of the child to hospitalisation', 'Regression',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520012', 'SATA',
 'A nurse is planning care for a hospitalised 4-year-old. Which actions support the psychosocial task of initiative described by Erikson? Select all that apply.',
 'The preschool years are the stage of initiative versus guilt, in which the child needs to start things, try things and be praised for effort rather than told to sit still and be done to. Nursing care supports this by offering genuine choices within safe limits, providing materials the child can start and finish, and inviting the child to help with parts of care. Doing everything for the child, or implying that questions and activity are a nuisance, produces the guilt half of the stage.',
 '{"options":[{"id":"A","text":"Let the child choose which flavour of medicine cup to use and which arm to have the blood pressure cuff on"},{"id":"B","text":"Provide art materials so the child can start and finish a picture"},{"id":"C","text":"Do all care tasks for the child so that energy is conserved"},{"id":"D","text":"Praise the child for helping to peel back the dressing tape"},{"id":"E","text":"Tell the child that asking so many questions is delaying the nurse"},{"id":"F","text":"Allow the child to help push the drip stand when walking to the playroom"}]}'::jsonb,
 '{"answers":["A","B","D","F"],"feedback":{"A":"Correct. Genuine choices within safe limits let the preschooler take initiative without the plan of care changing.","B":"Correct. Starting and completing a project is exactly the sense of purpose this stage is built on.","C":"Incorrect. Doing everything for the child removes the chance to initiate and encourages passivity and guilt.","D":"Correct. Praising a small contribution to care reinforces initiative and cooperation.","E":"Incorrect. Treating questions as a nuisance is the classic route to the guilt side of this stage.","F":"Correct. A safe, active job gives the child a real part in what is happening."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Psychosocial development', 'Initiative versus guilt',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520013', 'SATA',
 'A 9-year-old will remain in hospital for approximately six weeks. Which nursing actions best support the psychosocial development of a school-age child during a long admission? Select all that apply.',
 'School-age children are working on industry versus inferiority, and they build self-worth from finishing tasks, mastering skills and holding a place among peers. A long admission threatens all three, so nursing care deliberately protects schoolwork, offers projects the child can complete over days, and keeps classmates in contact. Isolating the child or taking over self-care tasks removes both the peer group and the sense of competence, producing the inferiority the stage is named for.',
 '{"options":[{"id":"A","text":"Arrange for the hospital teacher to continue schoolwork"},{"id":"B","text":"Encourage the child to work on a model or craft project across several days"},{"id":"C","text":"Allow classmates to visit and to send messages and cards"},{"id":"D","text":"Move the child to a single room to reduce noise and interruption"},{"id":"E","text":"Give the child a chart on which to record fluid intake and tick off completed tasks"},{"id":"F","text":"Take over all self-care tasks so that the child can rest"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Keeping up with schoolwork protects both competence and the return to school after discharge.","B":"Correct. A project carried through to completion is exactly how a school-age child builds a sense of industry.","C":"Correct. Peer contact matters increasingly at this age and reduces the isolation of a long admission.","D":"Incorrect. A single room without a clinical indication cuts the child off from the ward peer group during a six-week stay.","E":"Correct. A concrete record of completed tasks gives the child a visible measure of achievement and some control.","F":"Incorrect. Taking over self-care removes opportunities for mastery and fosters a sense of inferiority."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Psychosocial development', 'Industry versus inferiority in a long admission',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520014', 'SATA',
 'The mother of a hospitalised 20-month-old must leave the ward for several hours to collect her other children. Which nursing actions reduce the distress of the separation? Select all that apply.',
 'Object permanence is established by the second year, so a toddler knows the parent still exists but cannot yet hold on to the idea that she will return, which is what makes separation so distressing. Distress is reduced by an honest goodbye tied to a concrete return point, transitional objects that carry the parent presence, a familiar voice or face on a recording or photograph, and one consistent nurse rather than a rotating cast. Slipping away teaches the toddler that the parent can vanish at any moment, and threatening that crying will delay the return adds guilt to fear.',
 '{"options":[{"id":"A","text":"Ask the mother to say goodbye and say when she will be back, rather than slipping away unnoticed"},{"id":"B","text":"Keep an item belonging to the mother, such as a scarf, in the cot"},{"id":"C","text":"Assign the same nurse to the toddler for the remainder of the shift"},{"id":"D","text":"Tell the toddler that crying will make the mother stay away longer"},{"id":"E","text":"Offer a recorded voice message or a photograph of the mother"},{"id":"F","text":"Arrange for several different nurses to take turns distracting the toddler"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. An honest goodbye linked to a concrete return point builds trust; disappearing without warning increases vigilance and fear.","B":"Correct. A transitional object carrying the parent scent and presence comforts a toddler in her absence.","C":"Correct. One consistent nurse gives the toddler a substitute familiar figure rather than a stream of strangers.","D":"Incorrect. This makes the toddler feel responsible for the absence of the parent and adds guilt to the distress.","E":"Correct. A recorded voice or photograph keeps the parent present in a form the toddler can hold on to.","F":"Incorrect. A rotation of unfamiliar faces increases stranger anxiety instead of substituting for the parent."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Separation anxiety in the hospitalised toddler', 'Supporting the child when the parent leaves',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520015', 'MCQ',
 'Which toy is most appropriate for the nurse to provide for a hospitalised 8-month-old infant?',
 'Infants explore the world by mouthing, so any object small enough to pass through the tube of a toilet roll, or with parts that can detach, is a choking hazard until around 4 years of age. Balloons, whether inflated or burst, conform to the airway and are among the most lethal choking objects in childhood. A large, soft, washable toy that makes a sound matches sensorimotor exploration, is safe in the mouth and can be cleaned between uses.',
 '{"options":[{"id":"A","text":"A large soft cloth block with a bell sewn inside"},{"id":"B","text":"A set of small interlocking plastic bricks"},{"id":"C","text":"A jigsaw puzzle with twelve pieces"},{"id":"D","text":"A latex balloon on a string"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. A large, soft, washable toy that makes a sound suits sensorimotor mouthing exploration and carries no choking risk.","B":"Incorrect. Small interlocking bricks are a classic choking hazard for a child who explores by mouth.","C":"Incorrect. A twelve-piece jigsaw needs fine motor and problem-solving skills well beyond 8 months, and the pieces are small enough to swallow.","D":"Incorrect. Balloons, inflated or burst, mould to the airway and are among the most dangerous choking objects in childhood."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Not applicable',
 'Age-appropriate toy selection', 'Choking risk in infancy',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520016', 'SATA',
 'A 3-year-old is nursed in a cot and is receiving oxygen by head box. Which items should the nurse remove from the cot area? Select all that apply.',
 'Oxygen does not burn but it makes everything else burn far more readily, so an oxygen-enriched area must be kept free of anything that can spark or ignite. Battery-operated and electrical toys can spark at the contacts, metal toys can strike and spark, and wool and similar friction-generating fabrics build up static charge. Alcohol-based products are directly flammable. Washable plastic and cloth toys that generate no static are safe and can also be cleaned between uses.',
 '{"options":[{"id":"A","text":"A battery-operated musical toy"},{"id":"B","text":"A toy car with a metal body and metal wheels"},{"id":"C","text":"A wool blanket brought from home"},{"id":"D","text":"A soft washable cloth doll"},{"id":"E","text":"A bottle of alcohol-based hand rub left on the cot mattress"},{"id":"F","text":"A set of plastic stacking cups"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Battery and electrical toys can spark at the contacts and must be kept out of an oxygen-enriched area.","B":"Correct. Metal toys can strike against the cot and produce a spark.","C":"Correct. Wool generates static charge and is replaced with cotton bedding where oxygen is in use.","D":"Incorrect. A washable cloth doll produces no spark or static and is safe to leave with the child.","E":"Correct. Alcohol-based hand rub is flammable and must not be left inside an oxygen-enriched area.","F":"Incorrect. Plastic stacking cups are safe, washable and developmentally appropriate for a 3-year-old."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Respiratory',
 'Age-appropriate toy selection', 'Toy safety where oxygen is in use',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520017', 'MCQ',
 'A 5-year-old receiving chemotherapy has a neutrophil count of 0.4 x 10^9/L. The grandmother arrives with a large second-hand plush teddy bear for the child. Which action by the nurse is most appropriate?',
 'Porous toys such as plush animals cannot be cleaned effectively and act as fomites, holding dust, moisture and micro-organisms close to a child whose neutrophil count offers almost no defence. Hard, non-porous toys that can be washed with detergent and disinfected between uses give the same play value without the reservoir. The nurse explains the reason and offers a workable alternative rather than either allowing the risk or simply removing the gift, since play and the gesture of the grandmother both matter to the child.',
 '{"options":[{"id":"A","text":"Allow the bear at the bedside, because a familiar comfort toy reduces anxiety"},{"id":"B","text":"Explain that soft fabric toys hold dust and organisms, and offer hard washable toys that can be cleaned instead"},{"id":"C","text":"Send the bear to the sterile services department to be autoclaved"},{"id":"D","text":"Seal the bear in a clear plastic bag and keep it at the bedside until discharge"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A second-hand porous toy is a fomite reservoir and the comfort it gives does not outweigh the infection risk at a neutrophil count of 0.4 x 10^9/L.","B":"Correct. Hard, non-porous toys can be cleaned and disinfected between uses and give the same play value without acting as a reservoir.","C":"Incorrect. Autoclaving uses steam under pressure and would destroy a plush toy.","D":"Incorrect. A sealed, untouchable toy gives no play or comfort value while still occupying the bed space."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Immune',
 'Age-appropriate toy selection', 'Toys as fomites for the immunosuppressed child',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520018', 'MCQ',
 'Two 2-year-olds are in the ward playroom. Each is building with a separate set of blocks beside the other, with occasional glances but no shared activity. The mother of one child tells the nurse she is worried that her child is antisocial. Which response by the nurse is BEST?',
 'Play develops in a predictable sequence: solitary play in infancy, parallel play in toddlerhood, associative play in the preschool years and cooperative play with shared goals and rules from about 5 or 6 years. Parallel play, in which children play beside rather than with each other, is the expected form at 2 years and says nothing about future sociability. Forcing sharing before the child has the developmental skill for it produces conflict rather than progress.',
 '{"options":[{"id":"A","text":"Reassure her that playing alongside another child rather than with them is expected at 2 years of age"},{"id":"B","text":"Agree that a referral for social assessment would be sensible"},{"id":"C","text":"Ask the play specialist to make the two children share one set of blocks"},{"id":"D","text":"Explain that the behaviour is caused by the stress of being in hospital"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Parallel play, side by side rather than together, is the normal form of play at 2 years of age.","B":"Incorrect. Referral for expected developmental behaviour causes unnecessary alarm and uses resources without benefit.","C":"Incorrect. Forcing shared play before the skill has developed produces conflict, not social development.","D":"Incorrect. Attributing normal parallel play to hospital stress misinforms the mother and leaves her belief that something is wrong intact."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Not applicable',
 'Development of play', 'Parallel play in toddlerhood',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_520019', 'MATRIX',
 'A nurse observes children at play in different areas of a paediatric department. For each observation, select the type of play being demonstrated.',
 'Play matures alongside social and cognitive development, and each form appears in a predictable order. Solitary play, in which the infant plays alone and takes no notice of others, gives way to parallel play in the toddler, who plays beside another child with similar toys but no interaction. Associative play in the preschooler involves borrowing, lending and talking with no shared goal or assigned roles, while cooperative play from school age has an agreed goal, rules and roles. Knowing which form belongs to which age lets the nurse reassure a parent about normal behaviour and choose activities the child can actually manage.',
 '{"rows":[{"id":"r1","text":"A 6-month-old shaking a rattle alone in the cot, ignoring the infant beside her"},{"id":"r2","text":"Two 2-year-olds building separate towers side by side with identical blocks"},{"id":"r3","text":"Four 4-year-olds at a sand tray, lending each other spades and chatting, with no shared plan"},{"id":"r4","text":"Six 8-year-olds organising a team quiz with agreed rules and assigned roles"}],"columns":[{"id":"c1","text":"Solitary play"},{"id":"c2","text":"Parallel play"},{"id":"c3","text":"Associative play"},{"id":"c4","text":"Cooperative play"}],"row_label":"Observation"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c4"},"feedback":{}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Not applicable',
 'Development of play', 'Solitary, parallel, associative and cooperative play',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Select one column for each row.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MMR_520020', 'MATRIX_MR',
 'A nurse reviews toys brought onto the paediatric ward by visitors. For each toy, select every hazard that applies. Each toy has at least one hazard.',
 'Toy safety on a paediatric ward is assessed against three separate questions: can it be swallowed or aspirated, can it ignite or spark where oxygen is in use, and can it hold organisms next to a vulnerable child. A single toy can fail more than one of these tests, so each toy is screened against all three rather than cleared on one. Small parts and round objects threaten any child under about 4 years, battery and metal toys are excluded from oxygen-enriched areas, and porous second-hand items are excluded around neutropenia.',
 '{"rows":[{"id":"r1","text":"A bag of small glass marbles for an 18-month-old"},{"id":"r2","text":"A battery-operated toy car with small detachable wheels for a 2-year-old receiving oxygen by mask"},{"id":"r3","text":"A second-hand plush rabbit with sewn-on button eyes for a 3-year-old with neutropenia"},{"id":"r4","text":"A latex balloon for a 2-year-old"}],"columns":[{"id":"c1","text":"Choking or aspiration risk"},{"id":"c2","text":"Fire or spark risk where oxygen is in use"},{"id":"c3","text":"Infection risk"}],"row_label":"Toy"}'::jsonb,
 '{"cells":{"r1":["c1"],"r2":["c1","c2"],"r3":["c1","c3"],"r4":["c1"]},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Multisystem',
 'Age-appropriate toy selection', 'Screening toys for combined hazards',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply for each row.', 6, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_520021', 'MCQ',
 'At a routine community clinic visit a 15-month-old pulls to stand and cruises confidently around the furniture but does not yet walk without support. All other developmental findings are appropriate for the age. Which action should the nurse take?',
 'Developmental milestones are reached across a range of ages rather than on a fixed date, and independent walking normally appears at any point between 12 and 18 months. A 15-month-old who cruises already has the strength, balance and postural control required and needs more time, not investigation, provided the rest of the developmental picture is normal. Baby walkers are a recognised cause of falls down stairs and of scalds from reaching raised surfaces, and they do not bring walking forward.',
 '{"options":[{"id":"A","text":"Reassure the parents that independent walking may appear at any point up to 18 months, and arrange a review"},{"id":"B","text":"Refer the child immediately for neurological assessment"},{"id":"C","text":"Advise the parents to use a baby walker to speed up walking"},{"id":"D","text":"Tell the parents that the child has a developmental delay"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Walking appears anywhere from 12 to 18 months, and a cruising 15-month-old with otherwise normal development needs time and a planned review.","B":"Incorrect. Immediate referral for a child within the normal range causes needless alarm and consumes specialist capacity.","C":"Incorrect. Baby walkers cause falls and scald injuries and do not accelerate independent walking.","D":"Incorrect. Labelling a child within the normal range as delayed is inaccurate and distressing to the parents."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Musculoskeletal',
 'Developmental milestones', 'Range of normal for independent walking',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520022', 'MCQ',
 'A nurse assesses a 24-month-old at a health surveillance check. Which language finding is expected at this age?',
 'By 24 months a typical toddler has a spoken vocabulary of around 50 words or more, joins two words into simple phrases such as more juice, and is understood by a familiar adult roughly half the time. Single words with no combinations by 24 months, or an absence of recognisable words, are red flags that warrant hearing testing and speech and language referral. Full five-word to six-word sentences belong to the preschool years, so their absence at 2 years is not a concern.',
 '{"options":[{"id":"A","text":"Uses around 50 words, joins two words together, and is understood by a parent about half the time"},{"id":"B","text":"Uses single words only, with no two-word combinations"},{"id":"C","text":"Speaks in full sentences of five to six words"},{"id":"D","text":"Uses babbling only, with no recognisable words"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. A vocabulary of about 50 words, two-word phrases and roughly half of speech intelligible to a parent are the expected findings at 24 months.","B":"Incorrect. Absence of two-word combinations at 24 months is a red flag requiring hearing assessment and speech referral.","C":"Incorrect. Sentences of five to six words appear in the preschool years, not at 2 years.","D":"Incorrect. Babbling without recognisable words at 24 months is a significant delay needing prompt assessment."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological',
 'Developmental milestones', 'Expected language at 24 months',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_520023', 'SELECT_N',
 'A nurse reviews a 9-month-old infant at a developmental check. Which 3 findings should the nurse report for further assessment?',
 'Deciding whether a finding is a delay or simply a variation depends on knowing which skills should already be present and which are still emerging. By 9 months an infant should sit unsupported, babble with consonant sounds, and have lost the primitive reflexes of early infancy, so failure in any of these needs assessment. Cruising along furniture, a mature pincer grasp and clear single words normally appear between 9 and 12 months, so their absence at exactly 9 months sits within the range of normal and calls for review rather than referral.',
 '{"options":[{"id":"A","text":"Cannot sit without support"},{"id":"B","text":"Does not babble or make any consonant sounds"},{"id":"C","text":"Does not yet walk while holding on to furniture"},{"id":"D","text":"A persistent Moro reflex"},{"id":"E","text":"Is not yet using a mature pincer grasp"},{"id":"F","text":"Cannot yet say two clear single words"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","D"],"feedback":{"A":"Correct. Sitting unsupported is established by 8 to 9 months, so its absence needs assessment.","B":"Correct. Consonant babbling should be well established by 9 months, and its absence requires hearing testing.","C":"Incorrect. Cruising appears between 9 and 12 months, so not doing it at 9 months is within the normal range.","D":"Correct. The Moro reflex should have disappeared by 4 to 6 months, and persistence suggests a neurological problem.","E":"Incorrect. The mature pincer grasp emerges between 9 and 12 months and is still developing at this age.","F":"Incorrect. Clear single words typically appear around 12 months, so their absence at 9 months is expected."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological',
 'Developmental milestones', 'Distinguishing a red flag from a normal variation',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_CLZ_520024', 'CLOZE',
 'A nurse teaches a parent group about gross motor development. A healthy infant is expected to sit without support by about {1}, and the nurse should refer any child who is still not walking independently by {2}. Select the option that completes each sentence.',
 'Gross motor development proceeds head to toe and in a broad but predictable order, so each milestone has both a usual age and an upper limit beyond which assessment is warranted. Sitting without support is established at around 8 months, and independent walking usually appears between 12 and 18 months. Referral is triggered by the upper limit rather than the average, which is why a child not walking at 14 months is watched while one not walking at 18 months is referred.',
 '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"4 months"},{"id":"c2","text":"8 months"},{"id":"c3","text":"14 months"}]},{"id":"b2","choices":[{"id":"c1","text":"12 months"},{"id":"c2","text":"18 months"},{"id":"c3","text":"30 months"}]}]}'::jsonb,
 '{"answers":{"b1":"c2","b2":"c2"},"feedback":{}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Musculoskeletal',
 'Developmental milestones', 'Usual age and referral threshold',
 'Easy', 'CURATOR_LABEL', 'Remember', '{}', 'Complete the sentence by choosing from each drop-down.', 2, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520025', 'MCQ',
 'During a home visit the nurse watches a mother change the nappy of her 4-month-old on a high bed while turning away to reach for wipes on a chair. Which teaching point is most important?',
 'Safety teaching is retimed at every new motor milestone, because what a child can suddenly do changes what a child can suddenly fall from. Rolling from front to back appears at around 4 months, so from this age an infant left unattended on any raised surface can roll off in the second it takes an adult to turn away. The rule taught to parents is to keep one hand on the infant at all times or to change the nappy on the floor, and to bring all supplies within reach before starting.',
 '{"options":[{"id":"A","text":"Keep one hand on the infant at all times, because a baby of this age can roll over and fall"},{"id":"B","text":"Change the nappy on the floor to reduce strain on the back of the mother"},{"id":"C","text":"Warm the wipes before use to prevent a startle response"},{"id":"D","text":"Use cloth nappies rather than disposable ones to reduce nappy rash"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Rolling begins at around 4 months, so an infant left unattended on a raised surface can fall within seconds.","B":"Incorrect. Changing on the floor is a reasonable option, but the reason given here is the comfort of the mother rather than the fall risk to the infant.","C":"Incorrect. Wipe temperature is a comfort issue and does not address the immediate danger of a fall.","D":"Incorrect. Nappy type is unrelated to the safety problem being observed."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Musculoskeletal',
 'Injury prevention by developmental stage', 'Falls once rolling begins',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520026', 'MCQ',
 'A 3-year-old who has been taking prednisolone 2 mg/kg/day for the past eight weeks attends the clinic for the scheduled varicella vaccine. Which action should the nurse take?',
 'Live attenuated vaccines, which include varicella, MMR, rotavirus, live attenuated influenza, BCG and yellow fever, can produce disease rather than immunity in a child whose immune response is suppressed. A prednisolone dose of 2 mg/kg/day or more given for 14 days or longer counts as significant immunosuppression, so live vaccines are deferred until roughly one month after the course finishes. Inactivated vaccines may still be given, and vaccine doses are never halved, because the dose is fixed regardless of the size of the child.',
 '{"options":[{"id":"A","text":"Give the varicella vaccine as scheduled"},{"id":"B","text":"Withhold the vaccine and consult the prescriber, because high-dose corticosteroid therapy contraindicates a live vaccine"},{"id":"C","text":"Give half the usual dose to reduce the risk of a reaction"},{"id":"D","text":"Give the vaccine together with an oral antihistamine"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A live attenuated vaccine given during significant immunosuppression can cause the disease it is intended to prevent.","B":"Correct. Prednisolone at 2 mg/kg/day for 14 days or more is immunosuppressive, so live vaccines are deferred until about a month after the course ends.","C":"Incorrect. Vaccine doses are fixed and are never reduced; a half dose would give unreliable protection and would not remove the risk.","D":"Incorrect. An antihistamine does nothing to prevent replication of a live vaccine organism in an immunosuppressed child."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Immune',
 'Childhood immunisation', 'Contraindications to live vaccines',
 'Very hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_TF_520027', 'TF',
 'A 12-month-old attends the clinic for routine immunisation with a runny nose and a temperature of 37.6 degrees C, and is feeding and playing normally. The nurse should give the scheduled vaccines today. True or False?',
 'A mild illness, with or without a low-grade fever, is one of the most frequent false contraindications to immunisation and is a major cause of missed doses. Antibody response is not reduced by a coryzal illness, and postponing simply leaves the child unprotected for longer and risks the appointment never being rebooked. Only a moderate to severe acute illness, or a true contraindication such as anaphylaxis to a previous dose or component, justifies deferral.',
 '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. A mild illness with a low-grade fever is not a contraindication, and deferring the dose only prolongs the period without protection.","B":"Incorrect. Only a moderate to severe acute illness warrants postponement; treating minor coryza as a contraindication is a leading cause of missed immunisations."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Immune',
 'Childhood immunisation', 'False contraindications',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520028', 'SATA',
 'A mother tells the nurse she has read that vaccines overload the immune system of a baby, and she is unsure whether to continue with the next doses. Which nursing responses are appropriate? Select all that apply.',
 'Vaccine hesitancy is best met with curiosity rather than correction, because a parent who feels judged stops talking and simply does not return. The nurse first finds out what has been read and what specifically worries the parent, names the protective motive behind the question, and then offers accurate information in plain language. Keeping the door open with written material from a credible source and a further appointment preserves the relationship, whereas threats and abrupt closure end both the conversation and the chance of later uptake.',
 '{"options":[{"id":"A","text":"Ask what she has read and which part worries her most"},{"id":"B","text":"Acknowledge that wanting to protect her baby is what lies behind the question"},{"id":"C","text":"Tell her that refusing vaccination is neglectful and may have to be reported"},{"id":"D","text":"Explain in plain language that an infant meets far more antigens every day than are contained in the whole schedule"},{"id":"E","text":"Offer written information from a national immunisation source and arrange to talk again"},{"id":"F","text":"End the discussion and record that the mother has refused"}]}'::jsonb,
 '{"answers":["A","B","D","E"],"feedback":{"A":"Correct. Finding out what has actually been read allows the nurse to address the specific concern rather than a general one.","B":"Correct. Naming the protective motive behind the question keeps the parent engaged rather than defensive.","C":"Incorrect. Threatening a parent ends the conversation and makes a future return less likely.","D":"Correct. A concrete, plain-language comparison directly answers the overload belief being described.","E":"Correct. Credible written material plus a further appointment gives the parent time to consider without closing the door.","F":"Incorrect. Recording a refusal after one conversation forecloses a decision the mother has not yet made."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Immune',
 'Childhood immunisation', 'Responding to parental hesitancy',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520029', 'MCQ',
 'After teaching about care at home following routine immunisation, which statement by the parent of a 6-month-old indicates a need for further teaching?',
 'Evaluating teaching means listening for the one statement that would lead to harm rather than confirming the ones that are correct. Aspirin is avoided in children because of its association with Reye syndrome, an acute encephalopathy with hepatic failure, so paracetamol or ibuprofen are the antipyretics used after immunisation. A small firm red area at the injection site for a few days is an expected local reaction, and parents should be told which features, such as difficulty breathing or facial swelling, mean immediate return.',
 '{"options":[{"id":"A","text":"I will give paracetamol if my baby is uncomfortable or feverish"},{"id":"B","text":"I will give aspirin if the temperature goes above 38 degrees C"},{"id":"C","text":"A small red lump where the injection went in can last a few days"},{"id":"D","text":"I will bring my baby back straight away if there is difficulty breathing or swelling of the face"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Paracetamol is an appropriate antipyretic and analgesic after immunisation, so this statement needs no correction.","B":"Correct. Aspirin is avoided in children because of the risk of Reye syndrome, so this statement shows the teaching has not been understood.","C":"Incorrect. A small local red lump lasting a few days is an expected reaction and the parent has understood correctly.","D":"Incorrect. Recognising the features of an anaphylactic reaction and returning immediately is exactly what should be taught."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Immune',
 'Childhood immunisation', 'Evaluating post-immunisation teaching',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520030', 'MCQ',
 'A nurse records the following observations on a 6-month-old admitted with poor feeding: temperature 37.2 degrees C, heart rate 130 beats per minute, respiratory rate 68 breaths per minute, oxygen saturation 96 percent on air. Which finding should the nurse report?',
 'Expected vital sign ranges narrow steadily with age, so a value must always be read against the age of the child rather than against an adult standard. At 6 months the expected respiratory rate is roughly 25 to 55 breaths per minute and the expected heart rate roughly 100 to 160 beats per minute. A rate of 68 breaths per minute is therefore above range, and tachypnoea is one of the earliest and most sensitive signs of respiratory or metabolic compromise in an infant, appearing well before saturations fall.',
 '{"options":[{"id":"A","text":"Temperature 37.2 degrees C"},{"id":"B","text":"Heart rate 130 beats per minute"},{"id":"C","text":"Respiratory rate 68 breaths per minute"},{"id":"D","text":"Oxygen saturation 96 percent on air"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. 37.2 degrees C is within the normal range and requires no report.","B":"Incorrect. A heart rate of 130 beats per minute sits inside the expected 100 to 160 range for a 6-month-old.","C":"Correct. 68 breaths per minute exceeds the expected 25 to 55 range at this age and is an early sign of compromise.","D":"Incorrect. An oxygen saturation of 96 percent on air is acceptable and falls late in respiratory deterioration in infants."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Respiratory',
 'Paediatric vital sign ranges', 'Recognising tachypnoea in infancy',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MMR_520031', 'MATRIX_MR',
 'A nurse reviews the recorded observations of five children on a paediatric ward. For each child, select every statement that applies to the recorded values.',
 'Paediatric vital signs are read against age-specific ranges, and the change with age is large enough that the same number can be normal in one child and dangerous in another. As a working guide, heart rate falls from roughly 100 to 180 beats per minute in early infancy to 60 to 100 in adolescence, and respiratory rate falls from roughly 30 to 60 breaths per minute in early infancy to 12 to 20 in adolescence. Reading a value without the age attached is one of the commonest sources of both missed deterioration and unnecessary escalation.',
 '{"rows":[{"id":"r1","text":"A 2-month-old: heart rate 148 beats per minute, respiratory rate 42 breaths per minute"},{"id":"r2","text":"A 3-year-old: heart rate 168 beats per minute, respiratory rate 22 breaths per minute"},{"id":"r3","text":"An 8-year-old: heart rate 88 beats per minute, respiratory rate 38 breaths per minute"},{"id":"r4","text":"A 15-year-old: heart rate 52 beats per minute, respiratory rate 12 breaths per minute"},{"id":"r5","text":"A 6-month-old: heart rate 184 beats per minute, respiratory rate 64 breaths per minute"}],"columns":[{"id":"c1","text":"Heart rate outside the expected range for age"},{"id":"c2","text":"Respiratory rate outside the expected range for age"},{"id":"c3","text":"Both values within the expected range for age"}],"row_label":"Client"}'::jsonb,
 '{"cells":{"r1":["c3"],"r2":["c1"],"r3":["c2"],"r4":["c1"],"r5":["c1","c2"]},"feedback":{}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem',
 'Paediatric vital sign ranges', 'Interpreting values against age',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply for each row.', 6, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520032', 'MCQ',
 'A nurse beginning a shift on a paediatric ward receives handover on four children. Which child should the nurse assess FIRST?',
 'Prioritisation in paediatrics rests on age-adjusted physiology rather than on how large a number looks. Airway and breathing come before everything else, and in a small infant a markedly raised respiratory rate combined with grunting signals imminent decompensation, because respiratory reserve is small and deterioration is rapid once compensation fails. A comfortable febrile preschooler, a single vomit after anaesthesia and a moderate headache are all genuine needs, but none of them threatens ventilation in the next few minutes.',
 '{"options":[{"id":"A","text":"A 5-year-old with a temperature of 38.4 degrees C who is drinking and playing"},{"id":"B","text":"A 3-month-old with a respiratory rate of 72 breaths per minute and intermittent grunting"},{"id":"C","text":"An 8-year-old who has vomited once after a general anaesthetic"},{"id":"D","text":"A 14-year-old requesting analgesia for a headache scored 5 out of 10"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A febrile child who is drinking and playing is compensating well and can safely wait.","B":"Correct. Marked tachypnoea with grunting in a 3-month-old indicates failing respiratory compensation and takes priority over every other client here.","C":"Incorrect. A single post-anaesthetic vomit is common and needs assessment, but not before a threatened airway.","D":"Incorrect. Moderate pain deserves prompt attention but does not outrank an infant in respiratory distress."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Pediatrics', 'Respiratory',
 'Prioritisation in paediatric nursing', 'Sequencing assessment after handover',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_520033', 'MATRIX',
 'A nurse advises parents about child car restraints at a community clinic. For each child, select the restraint that is currently appropriate.',
 'Car restraint is matched to size and developmental stage rather than to age alone, and each stage is used until the child exceeds the height or weight limit printed on the seat. A rear-facing seat spreads crash forces across the whole back, head and neck and is used until at least 2 years of age; a forward-facing seat with a five-point harness follows; then a belt-positioning booster raises the child so the adult belt crosses the shoulder and hips rather than the neck and abdomen. The adult belt alone is used only when the child is tall enough for it to sit correctly, and children remain in a rear seat away from front airbags.',
 '{"rows":[{"id":"r1","text":"A 9-month-old weighing 9 kg, within the limits of the infant seat"},{"id":"r2","text":"A 3-year-old weighing 15 kg, within the harness limits of the seat"},{"id":"r3","text":"A 7-year-old weighing 25 kg who has outgrown the harnessed seat"},{"id":"r4","text":"A 13-year-old who is 165 cm tall and sits with the belt across the shoulder and hips"}],"columns":[{"id":"c1","text":"Rear-facing car seat"},{"id":"c2","text":"Forward-facing seat with a five-point harness"},{"id":"c3","text":"Belt-positioning booster seat"},{"id":"c4","text":"Adult seat belt alone, in a rear seat"}],"row_label":"Client"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c4"},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Not applicable',
 'Injury prevention by developmental stage', 'Car restraint selection',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 'Select one column for each row.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520034', 'SATA',
 'Which instructions should the nurse give the parents of a healthy newborn about safe sleep? Select all that apply.',
 'Sudden unexpected death in infancy is reduced by a small set of consistent measures, all aimed at protecting the airway and preventing overheating. The infant sleeps supine on a firm flat surface with nothing loose in the sleep space, in the room of the parents for the first six months, at a comfortable room temperature. Side sleeping is unstable and allows the infant to roll to the prone position, and sofas and armchairs carry a particularly high risk of wedging and suffocation when an adult falls asleep with the baby.',
 '{"options":[{"id":"A","text":"Place the baby on the back for every sleep, including naps"},{"id":"B","text":"Use a firm, flat mattress with no pillows, quilts or cot bumpers"},{"id":"C","text":"Keep the cot in the room of the parents for the first six months"},{"id":"D","text":"Place the baby on the side, wedged in position with a rolled towel"},{"id":"E","text":"Keep the room at about 16 to 20 degrees C and avoid overheating the baby"},{"id":"F","text":"Let the baby sleep on the sofa with a parent after the night feed"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Supine sleep for every sleep is the single most effective measure against sudden unexpected death in infancy.","B":"Correct. A firm flat surface with nothing loose in the cot prevents the airway being covered or the infant becoming wedged.","C":"Correct. Room sharing without bed sharing for the first six months is associated with a lower risk.","D":"Incorrect. Side lying is unstable and lets the infant roll prone, and wedging devices are themselves a suffocation hazard.","E":"Correct. Overheating raises the risk, so a moderate room temperature and light bedding are advised.","F":"Incorrect. Sleeping with an infant on a sofa or armchair carries a markedly increased risk of wedging and suffocation."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Respiratory',
 'Safe sleep for infants', 'Reducing sudden unexpected death in infancy',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_520035', 'SELECT_N',
 'During a home visit the nurse inspects the cot of a 5-month-old. Which 3 findings require intervention?',
 'A safe cot is a bare cot with a firm, well-fitting mattress and a frame that cannot trap any part of the infant. Slats must be no more than about 6 cm apart so that the body cannot slip between them and leave the head trapped, and a gap of that size means the cot must be replaced. Pillows and cot bumpers were once standard but are now excluded because they can cover the face of an infant who cannot yet lift or turn the head reliably, and the tie cords of bumpers add a strangulation risk.',
 '{"options":[{"id":"A","text":"The gap between the cot slats measures 8 cm"},{"id":"B","text":"Padded cot bumpers are tied along the inside of the cot sides"},{"id":"C","text":"A soft feather pillow is placed under the head of the infant"},{"id":"D","text":"The mattress fits the cot frame with no gap at the sides"},{"id":"E","text":"The cot sides are raised and locked when the infant is unattended"},{"id":"F","text":"The mattress is firm and flat with a fitted sheet only"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Slats more than about 6 cm apart allow the body to slip through and the head to become trapped, so the cot must be replaced.","B":"Correct. Cot bumpers can cover the face and their ties present a strangulation risk, so they are removed.","C":"Correct. A soft pillow is a suffocation hazard for an infant who cannot reliably lift or turn the head.","D":"Incorrect. A snugly fitting mattress is exactly what is wanted, because gaps at the sides trap limbs and heads.","E":"Incorrect. Raised and locked cot sides are correct practice and prevent falls.","F":"Incorrect. A firm flat mattress with a fitted sheet and nothing else is the recommended sleep surface."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Not applicable',
 'Cot and sleep environment safety', 'Identifying unsafe cot features',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520036', 'MCQ',
 'A mother telephones the community nurse to say her 2-year-old swallowed an unknown amount of a household drain cleaner about five minutes ago. The child is alert and crying. Which instruction should the nurse give FIRST?',
 'A caustic product burns the oesophagus on the way down and burns it a second time on the way back up, so induced vomiting doubles the injury and adds a risk of aspiration into the airway. The first action is to contact the poison centre with the container in hand, because the exact product, its concentration and the estimated quantity determine everything that follows. Routine dilution with milk or water is no longer advised before that specialist advice is obtained, and no caustic ingestion is safe to watch at home without expert direction.',
 '{"options":[{"id":"A","text":"Give the child a glass of milk to dilute the product"},{"id":"B","text":"Make the child vomit by placing a finger at the back of the throat"},{"id":"C","text":"Telephone the poison centre now with the product container in hand, and do not make the child vomit"},{"id":"D","text":"Wait one hour and see whether any symptoms develop"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. Routine dilution is not advised ahead of specialist guidance and delays the call that determines treatment.","B":"Incorrect. Induced vomiting brings the caustic back through the oesophagus, doubling the burn and risking aspiration.","C":"Correct. Contacting the poison centre with the container available identifies the product and concentration, which drives every subsequent decision.","D":"Incorrect. Waiting for symptoms after a caustic ingestion wastes the window in which treatment is most effective."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Gastrointestinal',
 'Childhood poisoning', 'First action after a caustic ingestion',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_520037', 'SELECT_N',
 'A nurse visits the home of an 8-month-old who has just begun to crawl. Which 3 findings should the nurse discuss with the parents as immediate hazards?',
 'Home hazard assessment is repeated at every new motor milestone, because mobility changes what a child can reach in a matter of days. An infant can drown in a few centimetres of water in a bucket, a hanging tablecloth invites a pull that brings scalding liquid down onto the child, and cleaning products at floor level become accessible the moment crawling starts. Stair gates, working smoke alarms and a cot placed clear of blind cords are protective measures rather than hazards and need only be acknowledged.',
 '{"options":[{"id":"A","text":"A bucket of mop water left standing on the kitchen floor"},{"id":"B","text":"A tablecloth hanging over the edge of a table set with a hot teapot"},{"id":"C","text":"A stair gate fitted at the top and the bottom of the stairs"},{"id":"D","text":"Cleaning products stored in an unlocked cupboard at floor level"},{"id":"E","text":"Smoke alarms fitted and tested on each floor"},{"id":"F","text":"The cot positioned well away from the window blind cords"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","D"],"feedback":{"A":"Correct. An infant can drown in a few centimetres of water, and a bucket is at exactly crawling height.","B":"Correct. A hanging tablecloth is a handhold that brings scalding liquid down onto a child who is pulling to stand.","C":"Incorrect. Stair gates at both the top and the bottom are the correct control for a newly mobile infant.","D":"Correct. Floor-level cleaning products are within reach from the day crawling begins and must be moved and locked.","E":"Incorrect. Working smoke alarms on each floor are a protective measure and require no action.","F":"Incorrect. Keeping the cot clear of blind cords removes a strangulation risk and is correct practice."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Not applicable',
 'Injury prevention by developmental stage', 'Home hazards for the newly mobile infant',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520038', 'SATA',
 'A nurse teaches the parents of a 2-year-old about preventing burns, scalds and drowning at home. Which instructions should the nurse include? Select all that apply.',
 'Toddlers combine new mobility with almost no sense of danger, so prevention relies on changing the environment rather than on instructing the child. Hot water is limited at the thermostat, pot handles are turned inwards, bath water is tested before the child gets in, and ignition sources are locked away. Water hazards are removed rather than supervised at a distance, since a toddler can drown silently in a few centimetres of water in a bucket or a toilet within seconds.',
 '{"options":[{"id":"A","text":"Set the hot water thermostat no higher than 49 degrees C and test the bath water before the child gets in"},{"id":"B","text":"Turn pot handles towards the back of the cooker"},{"id":"C","text":"Carry the child while drinking a hot drink so that both are in view"},{"id":"D","text":"Keep matches and lighters in a locked or high cupboard"},{"id":"E","text":"Empty buckets and paddling pools after use and keep the toilet lid closed"},{"id":"F","text":"Ask the 5-year-old sibling to watch the toddler while the paddling pool is in use"}]}'::jsonb,
 '{"answers":["A","B","D","E"],"feedback":{"A":"Correct. Limiting hot water at the thermostat and testing before immersion prevent tap water scalds, which are among the most severe burns in small children.","B":"Correct. Handles turned inwards cannot be grabbed by a toddler who is reaching upwards.","C":"Incorrect. Holding a child while drinking something hot is a leading cause of scalds and should be avoided entirely.","D":"Correct. Locking away ignition sources removes the means rather than relying on the toddler to obey a rule.","E":"Correct. A toddler can drown in a few centimetres of water, so standing water is emptied and the toilet lid kept closed.","F":"Incorrect. A 5-year-old cannot supervise, and water safety for a toddler requires an adult within arm reach at all times."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Integumentary',
 'Injury prevention by developmental stage', 'Burns, scalds and drowning in the toddler',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520039', 'MCQ',
 'A nurse is about to take a 4-year-old to theatre. Which statement to the child uses the most appropriate language for this age?',
 'Preschoolers think concretely and take words at their literal meaning, so figurative or borrowed medical phrases are heard exactly as spoken and frequently frighten. Being put to sleep is what happens to a pet that does not come back, a dye is heard as die, and taking a picture of the chest is far less alarming than an X-ray if the words are chosen with care. The rule is short, concrete, literal language, describing what the child will see, hear and feel rather than what will be done to the body.',
 '{"options":[{"id":"A","text":"The doctor will give you medicine that makes you sleep, and you will wake up again afterwards in this bed"},{"id":"B","text":"We are going to put you to sleep for a little while"},{"id":"C","text":"The anaesthetist will induce you shortly, so you will not feel anything"},{"id":"D","text":"You will be having a small procedure, so there is nothing to worry about"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Short concrete words that describe both the medicine and the waking up are literal, honest and reassuring for a preschooler.","B":"Incorrect. Put to sleep is what a preschooler associates with a pet that never came home, and the phrase regularly causes real terror.","C":"Incorrect. Medical terminology is meaningless to a preschooler and increases rather than reduces uncertainty.","D":"Incorrect. Nothing to worry about dismisses the fear without giving the child any concrete information to hold on to."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Pediatrics', 'Not applicable',
 'Communicating with children', 'Concrete literal language for the preschooler',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520040', 'SATA',
 'A nurse carries out a home safety review for a family with a 4-year-old. Which findings should the nurse address with the parents? Select all that apply.',
 'Preschoolers climb, imitate adults and cannot reliably distinguish a real weapon from a toy, so protection depends on physical barriers rather than on instruction. Firearms are stored unloaded and locked, with ammunition locked in a separate place, and teaching a child never to touch a gun has repeatedly been shown not to change what a curious 4-year-old actually does. Furniture placed under a window that opens fully turns the window into a climbing frame, and restrictors that limit the opening are the recommended control.',
 '{"options":[{"id":"A","text":"A firearm stored loaded in an unlocked bedside drawer"},{"id":"B","text":"Ammunition stored inside the same locked box as the firearm"},{"id":"C","text":"A bed placed directly beneath an upstairs window that opens fully"},{"id":"D","text":"Window restrictors fitted so that upstairs windows open no more than 10 cm"},{"id":"E","text":"The parents state that telling the child never to touch the gun is enough protection"},{"id":"F","text":"Blind cords secured on a cleat high on the wall"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. A loaded, unlocked firearm within reach of a preschooler is the highest-risk finding in this home and must be addressed immediately.","B":"Correct. Ammunition is stored locked and separate from the firearm, so a single opened box does not give access to a working weapon.","C":"Correct. Furniture under a fully opening upstairs window gives a preschooler the height needed to fall from it.","D":"Incorrect. Restrictors limiting the opening are the recommended control and need no change.","E":"Correct. Instruction alone does not stop a curious preschooler, so this belief must be corrected and physical storage arranged.","F":"Incorrect. Blind cords secured high on a cleat remove a strangulation risk and are correct practice."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Not applicable',
 'Injury prevention by developmental stage', 'Firearm storage and window falls',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_DO_520041', 'DRAG_ORDER',
 'A 10-month-old feeding in a highchair suddenly becomes silent, cannot cry or cough, and is turning blue. Place the nursing actions in the order in which they should be carried out.',
 'A silent, ineffective cough with cyanosis means the obstruction is complete, so help is summoned and relief is begun at once rather than after a period of observation. In an infant, cycles of five back blows followed by five chest thrusts are used, because abdominal thrusts risk injuring the large, poorly protected liver. The mouth is checked between cycles and an object removed only when it can be seen, since a blind finger sweep at any age can push the obstruction further into the airway.',
 '{"slots":[{"id":"s1","target_text":"1st"},{"id":"s2","target_text":"2nd"},{"id":"s3","target_text":"3rd"},{"id":"s4","target_text":"4th"}],"tokens":[{"id":"t1","text":"Call for help and confirm that the airway is completely obstructed"},{"id":"t2","text":"Support the infant face down along the forearm and give 5 back blows between the shoulder blades"},{"id":"t3","text":"Turn the infant face up and give 5 chest thrusts with two fingers on the lower sternum"},{"id":"t4","text":"Look inside the mouth and remove an object only if it can be seen"},{"id":"t5","text":"Perform a blind finger sweep of the mouth"}]}'::jsonb,
 '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Respiratory',
 'Choking in the infant', 'Sequence of relief for complete obstruction',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 'Place the options in the correct order.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_520042', 'SELECT_N',
 'A nurse teaches the mother of a 6-month-old about starting solid food. Which 3 statements by the mother indicate correct understanding?',
 'Solid food is introduced at around 6 months, when head control, sitting with support and the loss of the tongue-thrust reflex make spoon feeding both safe and possible. New foods are introduced singly with a gap of several days so that any reaction can be traced to one food, and iron-rich foods matter because the iron stores laid down before birth are running out at this age. Cereal added to a bottle bypasses the feeding skill the infant is learning and is linked to overfeeding and choking, and cow milk is not used as the main drink before 12 months because it is low in iron.',
 '{"options":[{"id":"A","text":"I will give one new single-ingredient food at a time and wait three to five days before adding another"},{"id":"B","text":"I will add baby cereal to the bottle so it is easier for her to take"},{"id":"C","text":"I will offer iron-rich foods such as pureed meat or fortified cereal"},{"id":"D","text":"I will switch her main drink to cow milk now that she is eating solids"},{"id":"E","text":"I will feed her sitting upright and supported, using a spoon"},{"id":"F","text":"I will add a little salt so that she enjoys the taste"}],"select_count":3}'::jsonb,
 '{"answers":["A","C","E"],"feedback":{"A":"Correct. Single foods spaced several days apart allow any allergy or intolerance to be traced to one specific food.","B":"Incorrect. Cereal in the bottle bypasses spoon feeding and is associated with overfeeding and choking.","C":"Correct. Iron stores from birth are depleted by around 6 months, so iron-rich first foods are recommended.","D":"Incorrect. Cow milk is not the main drink before 12 months because it is low in iron and may irritate the gut.","E":"Correct. Upright supported sitting with a spoon is the safe feeding position and develops the skill the infant needs.","F":"Incorrect. Salt is not added to infant food, because immature kidneys cannot handle the sodium load."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Pediatrics', 'Gastrointestinal',
 'Infant and child nutrition', 'Introducing solid food',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_520043', 'SELECT_N',
 'A nurse advises the parent of an 18-month-old about suitable finger foods. Which 3 foods should the nurse advise the parent to avoid?',
 'The airway of a toddler is roughly the diameter of the little finger of that child, and the molars needed to grind food are still erupting, so round, firm, smooth foods are the classic causes of fatal choking. Grapes, whole nuts, popcorn, whole cherry tomatoes and round slices of sausage make up most of the deaths recorded. Round foods are quartered lengthways rather than banned outright, and any food soft enough to be squashed between finger and thumb is safe to offer as a finger food at this age.',
 '{"options":[{"id":"A","text":"Whole grapes"},{"id":"B","text":"Soft banana slices"},{"id":"C","text":"Popcorn"},{"id":"D","text":"Cooked carrot sticks softened until they can be squashed"},{"id":"E","text":"Whole nuts"},{"id":"F","text":"Small pieces of ripe avocado"}],"select_count":3}'::jsonb,
 '{"answers":["A","C","E"],"feedback":{"A":"Correct. A whole grape is smooth, round and exactly the size of the toddler airway; grapes should be quartered lengthways.","B":"Incorrect. Soft banana slices squash easily and are a safe finger food at this age.","C":"Correct. Popcorn cannot be chewed adequately with erupting molars and is readily aspirated.","D":"Incorrect. Carrot cooked until it can be squashed between finger and thumb is safe; only raw hard carrot is a hazard.","E":"Correct. Whole nuts are hard, cannot be ground by an 18-month-old and are a leading cause of fatal aspiration.","F":"Incorrect. Ripe avocado is soft and easily managed, making it a suitable finger food."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Pediatrics', 'Gastrointestinal',
 'Infant and child nutrition', 'Safe finger foods for the toddler',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520044', 'MCQ',
 'The mother of a 3-year-old says her child eats almost nothing at some meals, refuses foods that were enjoyed last week, and is no longer gaining weight as quickly as before. The child is active and is tracking along the expected growth centile. Which response by the nurse is BEST?',
 'Growth velocity falls sharply after infancy, and the physiological anorexia of the preschool years is the direct consequence: appetite becomes erratic, portions look small to an adult and food preferences change from week to week. Where the child is active and tracking along a centile, the correct intervention is reassurance together with small portions, a regular meal pattern and no coercion. Pressure at the table creates a power struggle that a preschooler working on autonomy and initiative will win, entrenching the refusal, while supplements and referral are unwarranted when growth is normal.',
 '{"options":[{"id":"A","text":"Explain that appetite normally falls in the preschool years as growth slows, and advise offering small portions without pressure"},{"id":"B","text":"Advise adding a high-energy supplement drink to every meal"},{"id":"C","text":"Suggest keeping the child at the table until the plate is empty"},{"id":"D","text":"Refer the child to a dietitian for failure to thrive"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Slower growth after infancy produces an expected fall in appetite, and small unpressured portions are the appropriate response when growth is tracking normally.","B":"Incorrect. Supplements are unnecessary when the child is growing normally and tend to reduce appetite for ordinary food further.","C":"Incorrect. Coercion at the table turns eating into a power struggle and entrenches food refusal in a preschooler.","D":"Incorrect. Failure to thrive means faltering growth, which is not present in a child tracking along the expected centile."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Pediatrics', 'Gastrointestinal',
 'Infant and child nutrition', 'Physiological anorexia of the preschool years',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520045', 'SATA',
 'A nurse counsels a 14-year-old girl about nutrition during the adolescent growth spurt. Which teaching points are appropriate? Select all that apply.',
 'Adolescence brings the fastest growth since infancy, so energy, protein, iron and calcium requirements all rise rather than fall. Iron needs increase further once menstruation begins, and vitamin C taken alongside a plant source of iron markedly improves absorption. Around 90 percent of peak bone mass is laid down by the end of adolescence, which makes calcium and vitamin D intake now a determinant of fracture risk decades later, and sugary carbonated drinks work against this by displacing milk and increasing dental caries.',
 '{"options":[{"id":"A","text":"Iron requirements rise during adolescence and rise further once menstruation begins"},{"id":"B","text":"Calcium and vitamin D intake now helps determine the peak bone mass reached in early adulthood"},{"id":"C","text":"Skipping breakfast is an acceptable way to control weight during a growth spurt"},{"id":"D","text":"Sugary carbonated drinks displace milk from the diet and increase dental caries"},{"id":"E","text":"Energy requirements fall during the adolescent growth spurt"},{"id":"F","text":"Taking a source of vitamin C with a plant source of iron improves iron absorption"}]}'::jsonb,
 '{"answers":["A","B","D","F"],"feedback":{"A":"Correct. Expanding blood volume and muscle mass raise iron needs, and menstrual losses raise them further.","B":"Correct. Most peak bone mass is accrued by the end of adolescence, so intake now affects fracture risk for life.","C":"Incorrect. Skipping meals during the fastest growth phase since infancy compromises intake of iron, calcium and energy.","D":"Correct. Carbonated sugary drinks replace milk in the diet and add a direct dental caries risk.","E":"Incorrect. Energy requirements rise, not fall, during the adolescent growth spurt.","F":"Correct. Vitamin C converts non-haem iron to a more absorbable form and substantially increases uptake."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem',
 'Adolescent health promotion', 'Nutrition during the growth spurt',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520046', 'MCQ',
 'A 16-year-old attending a clinic appointment on her own asks the nurse whether what she says will be reported to her parents. Which reply is most appropriate?',
 'Confidentiality is what makes honest disclosure possible in adolescence, but it is never absolute and the limits must be stated at the beginning rather than discovered later. The nurse explains that most of the discussion stays within the consultation, and that involvement of others is required only where there is a serious risk of harm to the client or another person, or a safeguarding concern. Promising total secrecy is a promise that cannot be kept and destroys trust when it is broken, while stating that everything goes to the parents simply ends the conversation.',
 '{"options":[{"id":"A","text":"Everything we discuss here has to be shared with your parents until you are 18"},{"id":"B","text":"What you tell me stays between us, and there is nothing I would ever pass on"},{"id":"C","text":"Most of what we discuss stays confidential; I would only need to involve someone else if you or another person were at serious risk of harm"},{"id":"D","text":"I will decide at the end of the appointment what your parents need to know"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. A blanket statement that everything goes to the parents is inaccurate and ends any chance of honest disclosure.","B":"Incorrect. Absolute confidentiality cannot be promised, and breaking such a promise later destroys the relationship entirely.","C":"Correct. Stating the limits at the outset, tied to serious risk of harm, lets the adolescent make an informed choice about what to disclose.","D":"Incorrect. Leaving the decision unstated and taken later gives the adolescent no basis on which to decide what to say."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Pediatrics', 'Not applicable',
 'Adolescent health promotion', 'Confidentiality and its limits',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_520047', 'MATRIX',
 'A nurse in an adolescent clinic receives four disclosures. For each disclosure, select whether it can be handled within the consultation or must be escalated beyond it.',
 'Adolescent confidentiality is bounded by two clear triggers: a serious risk of harm to the client or to another person, and any safeguarding concern such as abuse or exploitation. Disclosures that fall outside those triggers, including embarrassing but low-risk health worries and risk-taking that calls for health education, are handled within the consultation with the confidentiality of the client preserved. Applying the triggers consistently is what allows an adolescent to trust that most of what is said stays private, which in turn makes the serious disclosures possible.',
 '{"rows":[{"id":"r1","text":"A 15-year-old asks about acne treatment and does not want her parents told she is worried about her skin"},{"id":"r2","text":"A 16-year-old describes a plan to end his life this weekend"},{"id":"r3","text":"A 14-year-old says she sometimes smokes cigarettes at the weekend"},{"id":"r4","text":"A 15-year-old discloses that an adult relative has been touching her"}],"columns":[{"id":"c1","text":"Handle within the consultation, confidentiality maintained"},{"id":"c2","text":"Must be escalated beyond the consultation"}],"row_label":"Disclosure"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Pediatrics', 'Psychiatric/Mental Health',
 'Adolescent health promotion', 'Deciding when a disclosure must be escalated',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select one column for each row.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520048', 'MCQ',
 'A 15-year-old girl is admitted for observation on day one after an appendicectomy. Four beds are available on the paediatric ward. Which room assignment is most appropriate?',
 'Room assignment balances infection risk against the developmental need of the client, and infection risk is settled first. An adolescent one day after surgery must not share with a child who has a transmissible infection or with a child requiring protective isolation, since the post-operative client is both a potential source and a potential recipient. Once infection considerations are excluded, the peer group becomes the deciding factor, because belonging and privacy are central adolescent needs and sharing a room with a preschooler is isolating rather than companionable.',
 '{"options":[{"id":"A","text":"A two-bed room with a 16-year-old girl who is also one day after abdominal surgery"},{"id":"B","text":"A two-bed room with a 15-year-old girl admitted with chickenpox"},{"id":"C","text":"A two-bed room with a 4-year-old girl awaiting a hernia repair"},{"id":"D","text":"A two-bed room with a 14-year-old girl receiving chemotherapy who is neutropenic"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. A peer of similar age with a comparable surgical experience poses no infection risk and meets the adolescent need for peer company.","B":"Incorrect. Chickenpox is highly contagious and requires airborne and contact precautions, so this client cannot share a room.","C":"Incorrect. A preschool roommate is developmentally isolating for an adolescent, whose peer group is central at this stage.","D":"Incorrect. A neutropenic client needs protective isolation, and a fresh post-operative wound in the same room adds avoidable risk."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Pediatrics', 'Immune',
 'Adolescent health promotion', 'Room assignment and peer group',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_520049', 'MCQ', 'A 5-month-old infant is seen at a routine child health clinic. The nurse notes bruises over both shins and one bruise over the left cheek. The parent explains that the infant is very active and bruises easily while kicking and rolling in the cot. Which action by the nurse is the PRIORITY?', 'Bruising is uncommon in an infant who cannot yet move independently. Rolling and kicking do not generate the force needed to bruise, so the parent explanation does not account for the findings. Bruising in a pre-mobile infant, and facial bruising in particular, is a recognised marker of inflicted injury and requires safeguarding referral rather than reassurance, advice or watchful waiting. Acting on the developmental implausibility is what protects the infant.', '{"options": [{"id": "A", "text": "Recognise that bruising is not expected in an infant who is not yet independently mobile, and refer under the safeguarding policy"}, {"id": "B", "text": "Reassure the parent that bruising becomes common once an infant starts to roll and kick"}, {"id": "C", "text": "Advise the parent to pad the sides of the cot to prevent further bruising"}, {"id": "D", "text": "Document the bruises and review the infant at the next scheduled appointment"}]}'::jsonb, '{"answer": "A", "feedback": {"A": "Correct. Bruising in an infant who is not yet independently mobile is a recognised marker of inflicted injury and warrants safeguarding referral.", "B": "Incorrect. Rolling and kicking do not generate enough force to bruise, so this reassurance normalises a red-flag finding.", "C": "Incorrect. Padding the cot accepts the account at face value and leaves the infant unprotected.", "D": "Incorrect. Documenting without referring delays protection until the next appointment."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Pediatrics', 'Integumentary', 'Safeguarding children', 'Bruising in the pre-mobile infant', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_520050', 'SATA',
 'A nurse assesses a 3-year-old brought to the emergency department after a fall. Which findings should increase the concern of the nurse about possible physical abuse? Select all that apply.',
 'Suspicion is raised by the pattern of the injury and by the fit between the injury and the account, rather than by the presence of an injury alone. Bruises of clearly different ages, marks that carry the shape of an implement, injuries on areas that are not struck in ordinary falls such as the buttocks, the ears and the inner thighs, and a delay in seeking help are all recognised features. Bruises over bony prominences such as the shins and forehead are the ordinary consequence of an active preschooler learning to run, and a consistent account given by both parents supports rather than undermines the history.',
 '{"options":[{"id":"A","text":"Bruises of several clearly different colours and ages on the back"},{"id":"B","text":"A bruise on the front of both shins"},{"id":"C","text":"A circular burn about 1 cm across on the back of the hand, with sharply defined edges"},{"id":"D","text":"A delay of two days between the reported fall and attending for care"},{"id":"E","text":"An account of the fall that is given consistently by both parents"},{"id":"F","text":"Bruising to the ear and the inner thigh"}]}'::jsonb,
 '{"answers":["A","C","D","F"],"feedback":{"A":"Correct. Multiple bruises of clearly different ages in one protected area suggest repeated injury rather than a single fall.","B":"Incorrect. Bruised shins are the ordinary result of an active preschooler running and falling.","C":"Correct. A small circular burn with sharply defined edges carries the pattern of a cigarette burn and must be investigated.","D":"Correct. An unexplained delay in seeking care for a painful injury is a recognised warning feature.","E":"Incorrect. A consistent account from both parents supports the history rather than raising concern.","F":"Correct. The ear and the inner thigh are protected sites that are not injured in ordinary falls."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Integumentary',
 'Safeguarding children', 'Injury patterns inconsistent with the history',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');
